entries[1301486] = { ["name"] = "Cursed Brilliant Silver", ["text"] = "5 yd range\n2.5 sec cast\nA higher grade of silver, Brilliant Silver's shine is as unmatched as its magical conductive properties. It is highly sought after as the epitome of form and function.\n\nThis deposit writhes with Ula'tek's curse. Standing near it makes the air feel heavier, as if drenched in the rage of every soul sacrificed on the altar of hubris." }
